import { ThresholdCrypto } from '../../packages/ztan-crypto/src/index';

async function main() {
  const payload = {
    version: 'ZTAN_CANONICAL_V1',
    auditId: 'RFC-COMPLEX-🎉-V1.4',
    timestamp: 1714732800000,
    payloadHash: 'd41d8cd98f00b204e9800998ecf8427e' + 'd41d8cd98f00b204e9800998ecf8427e', // 32 bytes
    threshold: 2,
    nodeIds: ['Node-C', 'Node-A', 'Node-B'] // Unsorted
  };

  const { canonicalHashHex, boundPayloadBytes } = ThresholdCrypto.buildCanonicalPayload(
    payload.auditId,
    payload.timestamp,
    payload.payloadHash,
    payload.threshold,
    payload.nodeIds
  );

  console.log(`COMPLEX_INPUT=${JSON.stringify(payload)}`);
  console.log(`COMPLEX_HEX=${Buffer.from(boundPayloadBytes).toString('hex')}`);
  console.log(`COMPLEX_HASH=${canonicalHashHex}`);
}

main().catch(console.error);

import * as fs from 'fs';
import * as path from 'path';
import { ThresholdCrypto } from '../src/crypto-utils';

async function verifyVector(filePath: string) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const vector = JSON.parse(content);
  
  console.log(`\n🔍 Verifying Vector: ${vector.id} - ${vector.description}`);
  
  if (vector.id === 'TV-001') {
    const canonicalIds = ThresholdCrypto.canonicalizeNodeIds(vector.input.participants).map(b => b.toString('hex'));
    const idMatch = JSON.stringify(canonicalIds) === JSON.stringify(vector.expected.canonicalParticipants);
    console.log(`${idMatch ? '✔' : '✖'} canonicalParticipants: ${idMatch ? 'MATCH' : 'FAIL'}`);
    
    const payloadBytes = Buffer.from(vector.input.payload.toString(), 'hex');
    const encoding = ThresholdCrypto.buildCanonicalPayload(payloadBytes, vector.input.threshold, vector.input.participants);
    const hexPayload = Buffer.from(encoding.boundPayloadBytes).toString('hex');
    const payloadMatch = hexPayload === vector.expected.canonicalPayloadHex;
    console.log(`${payloadMatch ? '✔' : '✖'} canonicalPayload: ${payloadMatch ? 'MATCH' : 'FAIL'}`);
    
    const hashMatch = encoding.canonicalHashHex === vector.expected.messageHash;
    console.log(`${hashMatch ? '✔' : '✖'} messageHash: ${hashMatch ? 'MATCH' : 'FAIL'}`);
    
    // We cannot fully verify the signature without the public key, but we can re-sign with the same share
    const fixedShare = BigInt('123456789012345678901234567890');
    const sig = await ThresholdCrypto.signPartial(vector.input.payload, fixedShare, 'nodea', vector.input.threshold, vector.input.participants);
    const sigMatch = sig.signature === vector.expected.signature;
    console.log(`${sigMatch ? '✔' : '✖'} signature: ${sigMatch ? 'MATCH' : 'FAIL'}`);
    
    const passed = idMatch && payloadMatch && hashMatch && sigMatch;
    console.log(`${passed ? '✔ verification: PASS' : '✖ verification: FAIL'}`);
    return passed;
  }
  
  if (vector.id === 'TV-002' || vector.id === 'TV-010') {
    const encodingA = ThresholdCrypto.buildCanonicalPayload(vector.inputA.payload.toString(), vector.inputA.threshold, vector.inputA.participants);
    const encodingB = ThresholdCrypto.buildCanonicalPayload(vector.inputB.payload.toString(), vector.inputB.threshold, vector.inputB.participants);
    
    const match = encodingA.canonicalHashHex === encodingB.canonicalHashHex;
    console.log(`${match ? '✔' : '✖'} Equivalence Match: ${match ? 'PASS' : 'FAIL'}`);
    return match === vector.expected.match;
  }
  
  if (vector.id === 'TV-009' || vector.id === 'TV-011' || vector.id === 'TV-012') {
    const payloadBytes = Buffer.from(vector.input.payload.toString(), 'hex');
    const participants = vector.input.participants || Array.from({length: vector.input.participantsCount}, (_, i) => `node_${i}`);
    
    const encoding = ThresholdCrypto.buildCanonicalPayload(payloadBytes, vector.input.threshold, participants);
    
    if (vector.expected.boundPayloadHex) {
        const payloadMatch = Buffer.from(encoding.boundPayloadBytes).toString('hex') === vector.expected.boundPayloadHex;
        console.log(`${payloadMatch ? '✔' : '✖'} Payload hex: ${payloadMatch ? 'PASS' : 'FAIL'}`);
        return payloadMatch;
    }
    
    const hashMatch = encoding.canonicalHashHex === vector.expected.canonicalHashHex;
    console.log(`${hashMatch ? '✔' : '✖'} Hash match: ${hashMatch ? 'PASS' : 'FAIL'}`);
    return hashMatch;
  }
  if (vector.id === 'TV-013' || vector.id === 'TV-014') {
    let errorThrown = false;
    try {
        ThresholdCrypto.buildCanonicalPayload(vector.input.payload.toString(), vector.input.threshold, vector.input.participants);
    } catch (e) {
        errorThrown = true;
    }
    const match = errorThrown === vector.expected.error;
    console.log(`${match ? '✔' : '✖'} Rejection behavior: ${match ? 'PASS' : 'FAIL'}`);
    return match;
  }
  
  return true;
}

async function run() {
  const dir = path.join(__dirname, '..', 'test_vectors');
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.json'));
  let allPass = true;
  for (const file of files) {
    const pass = await verifyVector(path.join(dir, file));
    console.log(`=> Result for ${file}: ${pass}`);
    if (!pass) allPass = false;
  }
  console.log(`Final allPass: ${allPass}`);
  if (!allPass) process.exit(1);
}

run().catch(console.error);

import { ThresholdCrypto } from '../../../packages/ztan-crypto/src/index';
import * as fs from 'fs';
import * as path from 'path';
import { execSync } from 'child_process';

async function runFuzzer() {
  console.log('--- ZTAN CROSS-RUNTIME DETERMINISM VALIDATION (100 CASES) ---');
  
  const cases: any[] = [];
  
  // 1. Edge Case Generator
  for (let i = 0; i < 100; i++) {
    const payload: any = {
      version: 'ZTAN_CANONICAL_V1',
      auditId: `FUZZ-${i}-${Math.random().toString(36).substring(7).toUpperCase()}`,
      timestamp: Date.now() + i,
      payloadHash: '8f92b4e28f92b4e28f92b4e28f92b4e28f92b4e28f92b4e28f92b4e28f92b4e2',
      threshold: 2 + (i % 3),
      nodeIds: ['nodeA', 'nodeB', 'nodeC', `node-Extra-${i}`]
    };

    // Add noise/entropy
    if (i % 5 === 0) payload.metadata = { unicode: '🚀 审计 🛡️', nested: { val: i } };
    if (i % 3 === 0) payload.nodeIds = payload.nodeIds.reverse(); // Disordered
    
    // Boundary Test: Large ID
    if (i === 99) {
        payload.auditId = "A".repeat(1024); // 1KB
        payload.nodeIds.push("B".repeat(255)); // Max nodeId
    }

    cases.push(payload);
  }

  // 2. Unicode Decomposition Parity Check (Adversarial)
  console.log('--- VERIFYING UNICODE DECOMPOSITION PARITY ---');
  const unicode1 = "ZTAN-UNICODE-\u00E9"; // NFC: é
  const unicode2 = "ZTAN-UNICODE-e\u0301"; // NFD: e + ́
  
  const p1 = { ...cases[0], auditId: unicode1 };
  const p2 = { ...cases[0], auditId: unicode2 };
  
  const h1 = (await ThresholdCrypto.verifyAudit(JSON.stringify(p1), { skipMarkSeen: true })).canonicalHash;
  const h2 = (await ThresholdCrypto.verifyAudit(JSON.stringify(p2), { skipMarkSeen: true })).canonicalHash;
  
  if (h1 === h2) {
    console.log('✔ Unicode Parity Verified: NFC/NFD equivalence confirmed via RFC-compliant normalization');
  } else {
    console.error('✖ FATAL: Unicode Parity Failure. Normalization is non-deterministic.');
    process.exit(1);
  }

  // 3. Whitespace Collision Test (Adversarial - RFC-001 v1.2)
  console.log('--- VERIFYING WHITESPACE SEMANTIC PRESERVATION ---');
  const id1 = "AUDIT-1";
  const id2 = " AUDIT-1";
  
  const hW1 = (await ThresholdCrypto.verifyAudit(JSON.stringify({ ...cases[0], auditId: id1 }), { skipMarkSeen: true })).canonicalHash;
  const hW2 = (await ThresholdCrypto.verifyAudit(JSON.stringify({ ...cases[0], auditId: id2 }), { skipMarkSeen: true })).canonicalHash;
  
  if (hW1 !== hW2) {
    console.log('✔ Whitespace Integrity Verified: "ID" and " ID" produce distinct hashes');
  } else {
    console.error('✖ FATAL: Whitespace Collision. Semantic trimming detected.');
    process.exit(1);
  }

  // 4. Invalid UTF-8 (Lone Surrogates) Rejection
  console.log('--- VERIFYING INVALID UTF-8 REJECTION ---');
  const invalidStr = "BAD-\uD800-SURROGATE";
  const result = await ThresholdCrypto.verifyAudit(JSON.stringify({ ...cases[0], auditId: invalidStr }), { skipMarkSeen: true });
  
  if (result.status === 'FAILED') {
    console.log('✔ Invalid UTF-8 correctly rejected.');
  } else {
    console.error('✖ FATAL: Accepted lone surrogate string.');
    process.exit(1);
  }

  // 5. RFC Vector Validation (RFC-001 v1.3)
  console.log('--- VERIFYING RFC v1.3 TEST VECTOR ---');
  const rfcPayload = {
    version: 'ZTAN_CANONICAL_V1',
    auditId: 'RFC-TEST-V1.3',
    timestamp: 1714732800000,
    payloadHash: '8f92b4e28f92b4e28f92b4e28f92b4e28f92b4e28f92b4e28f92b4e28f92b4e2',
    threshold: 2,
    nodeIds: ['nodeA', 'nodeB']
  };
  const expectedHash = "6b0cfaedff2ec7a1f0feb8f66c2f826b05a6faa55014b44ffc96d01f9790aec2";
  const rfcResult = await ThresholdCrypto.verifyAudit(JSON.stringify(rfcPayload), { skipMarkSeen: true });
  if (rfcResult.canonicalHash === expectedHash) {
    console.log('✔ RFC v1.3 Test Vector Verified: Implementation matches published spec');
  } else {
    console.error(`✖ FATAL: RFC Vector Mismatch. Got ${rfcResult.canonicalHash}, Expected ${expectedHash}`);
    process.exit(1);
  }

  // 6. Unknown Version Rejection
  console.log('--- VERIFYING UNKNOWN VERSION REJECTION ---');
  const badVersion = { ...rfcPayload, version: 'ZTAN_CANONICAL_V2' };
  const verResult = await ThresholdCrypto.verifyAudit(JSON.stringify(badVersion), { skipMarkSeen: true });
  if (verResult.status === 'FAILED') {
    console.log('✔ Unknown versionTag correctly rejected.');
  } else {
    console.error('✖ FATAL: Accepted unknown versionTag.');
    process.exit(1);
  }

  // 7. Oversize Rejection (Audit ID)
  console.log('--- VERIFYING OVERSIZE FIELD REJECTION ---');
  const hugeId = "A".repeat(1024 * 1024 + 1); // 1MB + 1
  const hugeResult = await ThresholdCrypto.verifyAudit(JSON.stringify({ ...rfcPayload, auditId: hugeId }), { skipMarkSeen: true });
  if (hugeResult.status === 'FAILED') {
    console.log('✔ Oversize auditId correctly rejected.');
  } else {
    console.error('✖ FATAL: Accepted oversized auditId.');
    process.exit(1);
  }

  // 8. Complex Adversarial Vector Validation (RFC-001 v1.4)
  console.log('--- VERIFYING RFC v1.4 COMPLEX VECTOR (UNICODE + SORTING) ---');
  const complexPayload = {
    version: 'ZTAN_CANONICAL_V1',
    auditId: 'RFC-COMPLEX-🎉-V1.4',
    timestamp: 1714732800000,
    payloadHash: 'd41d8cd98f00b204e9800998ecf8427ed41d8cd98f00b204e9800998ecf8427e',
    threshold: 2,
    nodeIds: ['Node-C', 'Node-A', 'Node-B']
  };
  const expectedComplexHash = "7289f43e5f05ee3e51a1bec6fc5d3cd04b7fd40c315a1296ca4d10d4dd5ff402";
  const complexResult = await ThresholdCrypto.verifyAudit(JSON.stringify(complexPayload), { skipMarkSeen: true });
  if (complexResult.canonicalHash === expectedComplexHash) {
    console.log('✔ RFC v1.4 Complex Vector Verified: Sorting and Unicode handling match published spec');
  } else {
    console.error(`✖ FATAL: Complex Vector Mismatch. Got ${complexResult.canonicalHash}, Expected ${expectedComplexHash}`);
    process.exit(1);
  }

  // 9. NFC Duplicate Rejection
  console.log('--- VERIFYING NFC DUPLICATE REJECTION ---');
  const dupePayload = {
    ...rfcPayload,
    nodeIds: ["e\u0301", "é"] // Collide to same NFC form
  };
  const dupeResult = await ThresholdCrypto.verifyAudit(JSON.stringify(dupePayload), { skipMarkSeen: true });
  if (dupeResult.status === 'FAILED') {
    console.log('✔ Duplicate IDs after NFC correctly rejected.');
  } else {
    console.error('✖ FATAL: Accepted duplicate IDs after normalization.');
    process.exit(1);
  }

  let passed = 0;
  const bundleDir = path.join(__dirname, '../fuzz_bundles');
  if (!fs.existsSync(bundleDir)) fs.mkdirSync(bundleDir);

  for (const [index, auditData] of cases.entries()) {
    const rawInput = JSON.stringify(auditData);
    
    // Step 1: Node Verification & Bundle Export
    const initial = await ThresholdCrypto.verifyAudit(rawInput, { skipMarkSeen: true });
    
    const anchor = initial.finalAnchor!;
    const threshold = auditData.threshold;
    const partialSigs = await Promise.all(auditData.nodeIds.slice(0, threshold).map(async (id: string) => ({
      verifierId: id,
      signature: await ThresholdCrypto.signAnchor(anchor, id)
    })));

    const consensusInput = { ...auditData, partialAnchorSignatures: partialSigs, consensusThreshold: threshold };
    const finalResult = await ThresholdCrypto.verifyAudit(JSON.stringify(consensusInput), { skipMarkSeen: true });

    const bundle = {
      version: 'ZTAN_AUDIT_EVIDENCE_V1.1',
      input: { raw: rawInput, fingerprint: initial.inputHash },
      consensus: {
        status: finalResult.status,
        signatures: finalResult.signatureMetadata,
        threshold: threshold,
        payloadHash: finalResult.inputHash
      },
      integrity: {
        canonicalHash: finalResult.canonicalHash,
        finalAnchor: finalResult.finalAnchor,
        traceChain: finalResult.traceHashChain
      },
      reproducibility: {
        algorithms: { hashing: 'SHA-256', signatures: 'BLS12-381-AGG' },
        spec: 'ZTAN_CANONICAL_V1'
      }
    };

    const bundlePath = path.join(bundleDir, `fuzz-proof-${index}.json`);
    fs.writeFileSync(bundlePath, JSON.stringify(bundle, null, 2));

    // Step 2: Python Independent Verification
    try {
      execSync(`python auditor/auditor_verifier.py ${bundlePath}`, { stdio: 'pipe' });
      passed++;
      if (passed % 20 === 0) console.log(`Progress: ${passed}/100 cases verified across runtimes...`);
    } catch (e: any) {
      console.error(`✖ FUZZ CASE ${index} FAILED CROSS-RUNTIME VERIFICATION`);
      console.error(e.stdout.toString());
      console.error(e.stderr.toString());
      process.exit(1);
    }
  }

  console.log(`\n✔ VALIDATION SUCCESS: 100/100 cases verified (Node.js <-> Python)`);
  console.log('✔ All adversarial edge cases (Unicode, Reordering, Thresholds) passed byte-parity checks.');
  console.log('✔ Determinism validated across independent runtimes following ZTAN-RFC-001.');
}

runFuzzer().catch(console.error);

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { ThresholdCrypto } from '../src/crypto-utils';

const VECTORS_DIR = path.join(__dirname, '..', 'test_vectors');

function hashPayload(data: string): string {
  return crypto.createHash('sha256').update(data).digest('hex');
}

if (!fs.existsSync(VECTORS_DIR)) {
  fs.mkdirSync(VECTORS_DIR, { recursive: true });
}

async function generateVectors() {
  console.log('Generating deterministic test vectors...');
  
  // Create deterministic node keys for testing
  const threshold = 3;
  
  // We need a static secret share to make the signatures deterministic for the test vectors.
  const fixedShare = BigInt('123456789012345678901234567890');
  
  // TV-001: Dedup + normalize + sort
  const tv001Payload = hashPayload('payload_123');
  const tv001Nodes = ['NodeB', 'nodea', 'NODEA', 'nodeb '];
  
  const canonical001 = ThresholdCrypto.canonicalizeNodeIds(tv001Nodes).map(b => b.toString('hex'));
  const encoding001 = ThresholdCrypto.buildCanonicalPayload(tv001Payload, 2, tv001Nodes);
  
  const sig001 = await ThresholdCrypto.signPartial(tv001Payload, fixedShare, 'nodea', 2, tv001Nodes);
  
  const tv001 = {
    id: 'TV-001',
    description: 'Canonical signer set normalization',
    input: {
      payload: tv001Payload,
      participants: tv001Nodes,
      threshold: 2
    },
    expected: {
      canonicalParticipants: canonical001,
      canonicalPayloadHex: Buffer.from(encoding001.boundPayloadBytes).toString('hex'),
      messageHash: encoding001.canonicalHashHex,
      signature: sig001.signature,
      valid: true
    }
  };
  fs.writeFileSync(path.join(VECTORS_DIR, 'tv-001.json'), JSON.stringify(tv001, null, 2));

  // TV-002: Ordering invariance
  const tv002NodesA = ['a', 'b', 'c'];
  const tv002NodesB = ['c', 'a', 'b'];
  const sig002A = await ThresholdCrypto.signPartial(tv001Payload, fixedShare, 'a', 2, tv002NodesA);
  const sig002B = await ThresholdCrypto.signPartial(tv001Payload, fixedShare, 'a', 2, tv002NodesB);
  
  const tv002 = {
    id: 'TV-002',
    description: 'Ordering invariance',
    inputA: { payload: tv001Payload, participants: tv002NodesA, threshold: 2 },
    inputB: { payload: tv001Payload, participants: tv002NodesB, threshold: 2 },
    expected: {
      match: true,
      signatureMatch: sig002A.signature === sig002B.signature
    }
  };
  fs.writeFileSync(path.join(VECTORS_DIR, 'tv-002.json'), JSON.stringify(tv002, null, 2));

  // TV-009: Delimiter collision
  const tv009Payload = hashPayload('abc|def,123');
  const encoding009 = ThresholdCrypto.buildCanonicalPayload(tv009Payload, 2, tv001Nodes);
  const tv009 = {
    id: 'TV-009',
    description: 'Delimiter collision safety',
    input: { payload: tv009Payload, participants: tv001Nodes, threshold: 2 },
    expected: {
      canonicalHashHex: encoding009.canonicalHashHex,
      boundPayloadHex: Buffer.from(encoding009.boundPayloadBytes).toString('hex')
    }
  };
  fs.writeFileSync(path.join(VECTORS_DIR, 'tv-009.json'), JSON.stringify(tv009, null, 2));

  // TV-010: Unicode normalization
  const tv010NodesA = ['nóde']; // Precomposed
  const tv010NodesB = ['no\u0301de']; // Decomposed
  const payload010 = hashPayload('payload');
  const encoding010A = ThresholdCrypto.buildCanonicalPayload(payload010, 1, tv010NodesA);
  const encoding010B = ThresholdCrypto.buildCanonicalPayload(payload010, 1, tv010NodesB);
  const tv010 = {
    id: 'TV-010',
    description: 'Unicode normalization equivalence',
    inputA: { payload: payload010, participants: tv010NodesA, threshold: 1 },
    inputB: { payload: payload010, participants: tv010NodesB, threshold: 1 },
    expected: {
      match: encoding010A.canonicalHashHex === encoding010B.canonicalHashHex
    }
  };
  fs.writeFileSync(path.join(VECTORS_DIR, 'tv-010.json'), JSON.stringify(tv010, null, 2));

  // TV-011: Binary payload
  const tv011Payload = crypto.randomBytes(32).toString('hex');
  const encoding011 = ThresholdCrypto.buildCanonicalPayload(tv011Payload, 2, tv001Nodes);
  const tv011 = {
    id: 'TV-011',
    description: 'Binary payload encoding',
    input: { payload: tv011Payload, participants: tv001Nodes, threshold: 2 },
    expected: {
      canonicalHashHex: encoding011.canonicalHashHex,
      boundPayloadHex: Buffer.from(encoding011.boundPayloadBytes).toString('hex')
    }
  };
  fs.writeFileSync(path.join(VECTORS_DIR, 'tv-011.json'), JSON.stringify(tv011, null, 2));

  // TV-012: Large input boundary
  const largePayload = hashPayload('a'.repeat(100000)); // Hashed to 32 bytes
  const largeParticipants = Array.from({ length: 100 }, (_, i) => `node${i}`);
  const encoding012 = ThresholdCrypto.buildCanonicalPayload(largePayload, 50, largeParticipants);
  const tv012 = {
    id: 'TV-012',
    description: 'Large input boundary safety',
    input: { payload: largePayload, participants: largeParticipants, threshold: 50 },
    expected: {
      canonicalHashHex: encoding012.canonicalHashHex,
      boundPayloadHex: Buffer.from(encoding012.boundPayloadBytes).toString('hex')
    }
  };
  fs.writeFileSync(path.join(VECTORS_DIR, 'tv-012.json'), JSON.stringify(tv012, null, 2));

  // TV-013: Empty Participant List Rejection
  let tv013Error = false;
  const errorPayload = hashPayload('error_payload');
  try {
      ThresholdCrypto.buildCanonicalPayload(errorPayload, 2, []);
  } catch (e) {
      tv013Error = true;
  }
  const tv013 = {
    id: 'TV-013',
    description: 'Rejection of empty participant lists',
    input: { payload: errorPayload, participants: [], threshold: 2 },
    expected: { error: true, errorEncountered: tv013Error }
  };
  fs.writeFileSync(path.join(VECTORS_DIR, 'tv-013.json'), JSON.stringify(tv013, null, 2));

  // TV-014: Threshold Exceeds Participants Rejection
  let tv014Error = false;
  try {
      ThresholdCrypto.buildCanonicalPayload(errorPayload, 3, ['nodeA', 'nodeB']);
  } catch (e) {
      tv014Error = true;
  }
  const tv014 = {
    id: 'TV-014',
    description: 'Rejection of threshold exceeding participants',
    input: { payload: errorPayload, participants: ['nodeA', 'nodeB'], threshold: 3 },
    expected: { error: true, errorEncountered: tv014Error }
  };
  fs.writeFileSync(path.join(VECTORS_DIR, 'tv-014.json'), JSON.stringify(tv014, null, 2));

  console.log('Test vectors generated successfully in test_vectors/');
}

generateVectors().catch(console.error);

import { ThresholdCrypto } from '../../../packages/ztan-crypto/src/index';
import * as fs from 'fs';

async function proveDeterminism() {
  console.log('--- ZTAN DETERMINISM PROOF ---');
  
  const rawInput = JSON.stringify({
    version: 'ZTAN_CANONICAL_V1',
    auditId: 'TEST-DETERMINISM-001',
    timestamp: 1714732800000,
    payloadHash: '8f92b4e28f92b4e28f92b4e28f92b4e28f92b4e28f92b4e28f92b4e28f92b4e2',
    threshold: 2,
    nodeIds: ['nodeA', 'nodeB', 'nodeC']
  });

  // Run 1
  const r1 = await ThresholdCrypto.verifyAudit(rawInput, { skipMarkSeen: true });
  const bundle1 = {
    integrity: {
      canonicalHash: r1.canonicalHash,
      finalAnchor: r1.finalAnchor,
      inputHash: r1.inputHash
    },
    version: 'ZTAN_AUDIT_EVIDENCE_V1.1'
  };
  const s1 = JSON.stringify(bundle1, Object.keys(bundle1).sort(), 2);

  // Run 2
  const r2 = await ThresholdCrypto.verifyAudit(rawInput, { skipMarkSeen: true });
  const bundle2 = {
    integrity: {
      canonicalHash: r2.canonicalHash,
      finalAnchor: r2.finalAnchor,
      inputHash: r2.inputHash
    },
    version: 'ZTAN_AUDIT_EVIDENCE_V1.1'
  };
  const s2 = JSON.stringify(bundle2, Object.keys(bundle2).sort(), 2);

  if (s1 === s2) {
    console.log('✔ DETERMINISM PROVED: Byte-identical output across runs.');
    console.log('Canonical Hash:', r1.canonicalHash);
    console.log('Anchor Root:   ', r1.finalAnchor);
  } else {
    console.error('✖ DETERMINISM FAILED: Drift detected between runs.');
    process.exit(1);
  }
}

proveDeterminism().catch(console.error);

#!/usr/bin/env node

import { Command } from 'commander';
import fs from 'fs';
import path from 'path';
import chalk from 'chalk';
import { ThresholdCrypto } from '@packages/ztan-crypto';
import { FileReplayGuard } from '@packages/ztan-crypto/src/node-replay';

const program = new Command();

const REPLAY_DB = path.join(process.cwd(), '.ztan_replay_db.json');
const guard = new FileReplayGuard(REPLAY_DB);

program
  .name('ztan-verify')
  .description('ZTAN Audit Verifier CLI')
  .argument('<file>', 'audit input file (json)')
  .option('-j, --json', 'output raw JSON result for pipelines')
  .option('-s, --silent', 'suppress all output except exit code')
  .option('-t, --threshold <count>', 'simulated consensus threshold', '3')
  .option('-e, --export <path>', 'export evidence bundle')
  .action(async (file, options) => {
    try {
      if (!fs.existsSync(file)) {
        if (!options.silent) console.error(`Error: File not found: ${file}`);
        process.exit(1);
      }

      const inputRaw = fs.readFileSync(file, 'utf-8').trim();
      const inputData = JSON.parse(inputRaw);
      
      // Step 1: Initial verification for anchor (SKIP MARK SEEN)
